import pytest

# Import the function to test
# from your_module import topological_sort

# For completeness, include the function definition (in real tests, import it)
def topological_sort(graph: dict) -> list:
    visited = set()
    result = []
    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph.get(node, []):
            dfs(neighbor)
        result.append(node)
    for node in graph:
        dfs(node)
    return result[::-1]


# Helper to validate a topological ordering
def is_valid_topological_order(graph: dict, order: list) -> bool:
    """Check if `order` is a valid topological sort of `graph`."""
    # Collect all nodes (keys + neighbors)
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    if set(order) != all_nodes:
        return False

    position = {node: i for i, node in enumerate(order)}
    for node, neighbors in graph.items():
        for neighbor in neighbors:
            if position[node] > position[neighbor]:
                return False
    return True


# ---------- Happy Path ----------
def test_empty_graph():
    assert topological_sort({}) == []


def test_single_node():
    assert topological_sort({1: []}) == [1]


def test_simple_dag():
    graph = {1: [2, 3], 2: [4], 3: [4], 4: []}
    result = topological_sort(graph)
    assert is_valid_topological_order(graph, result)


def test_linear_dag():
    graph = {'a': ['b'], 'b': ['c'], 'c': []}
